const body = $input.first().json.body;
if (!body || typeof body !== 'object' || Array.isArray(body)) {
  throw new Error('Bitte ein JSON-Objekt im Request-Body senden.');
}
const id = Number(body.datensatz_id);
if (!Number.isInteger(id) || id < 1 || id > 100) {
  throw new Error('Für die Test-API bitte datensatz_id zwischen 1 und 100 angeben.');
}
const bericht = String(body.bericht ?? '').trim();
if (!bericht) throw new Error('Bitte das Pflichtfeld bericht ausfüllen.');
return [{ json: { datensatz_id: id, body: bericht } }];
